import React, {
  FunctionComponent,
  useCallback,
  useEffect,
  useState,
} from 'react'
import { graphql } from 'gatsby'

import Template from 'components/Common/Template'
import Introduction from 'components/Main/Introduction'
import PostList from 'components/Main/PostList'
import { PostListItemType } from 'types/PostItem.types'
import { useSelectedCategory } from 'hooks/useCategories'

type IndexPageProps = {
  location: {
    search: string
  }
  data: {
    site: {
      siteMetadata: {
        title: string
        description: string
        siteUrl: string
      }
    }
    allMarkdownRemark: {
      edges: PostListItemType[]
    }
  }
}

const IndexPage: FunctionComponent<IndexPageProps> = function ({
  location: { search },
  data: {
    site: {
      siteMetadata: { title, description, siteUrl },
    },
    allMarkdownRemark: { edges },
  },
}) {
  const selectedCategory = useSelectedCategory(search)

  const initIntroState =
    typeof window !== 'undefined'
      ? sessionStorage.getItem('initIntroState')
      : null
  const [isIntro, setIsIntro] = useState<boolean>(
    initIntroState === 'false' ? false : true,
  )

  const hideIntro = useCallback(() => {
    if (isIntro === true) {
      setIsIntro(false)
      sessionStorage.setItem('initIntroState', 'false')
      setTimeout(() => {
        document.body.style.overflow = 'auto'
      }, 1000)
    }
  }, [])

  useEffect(() => {
    if (isIntro === true) {
      document.body.style.overflow = 'hidden'
    }
  }, [])

  return (
    <Template
      title={title}
      description={description}
      url={siteUrl}
      image={undefined}
      isIntro={isIntro}
    >
      <Introduction isIntro={isIntro} hideIntro={hideIntro} />
      <PostList selectedCategory={selectedCategory} posts={edges} />
    </Template>
  )
}

export default IndexPage

export const getPostList = graphql`
  query getPostList {
    site {
      siteMetadata {
        title
        description
        siteUrl
      }
    }
    allMarkdownRemark(
      sort: [{ frontmatter: { date: DESC } }, { frontmatter: { title: DESC } }]
    ) {
      edges {
        node {
          id
          fields {
            slug
          }
          frontmatter {
            title
            series
            summary
            date(formatString: "YYYY.MM.DD")
            categories
            tags
            thumbnail {
              childImageSharp {
                gatsbyImageData(width: 768, height: 400)
              }
            }
          }
        }
      }
    }
  }
`
